package com.boutique.checkout.service;
import com.boutique.checkout.client.CheckoutClients;import com.boutique.checkout.dto.*;import org.slf4j.*;import org.springframework.stereotype.Service;
@Service
public class CheckoutService{
 private static final Logger log=LoggerFactory.getLogger(CheckoutService.class);private final CheckoutClients clients;public CheckoutService(CheckoutClients clients){this.clients=clients;}
 public CheckoutResponse checkout(CheckoutRequest request){var cart=clients.getCart(request.userId());if(cart==null||cart.items()==null||cart.items().isEmpty())throw new IllegalStateException("Cart is empty.");if(cart.items().stream().anyMatch(i->!i.available()))throw new IllegalStateException("Cart contains unavailable items.");var order=clients.createOrder(new CheckoutClients.OrderCreate(request.userId(),request.idempotencyKey(),cart.items().stream().map(i->new CheckoutClients.OrderItem(i.productId(),i.sku(),i.name(),i.unitPrice(),i.quantity(),i.lineTotal())).toList(),cart.subtotal(),cart.currency()));boolean reserved=false,committed=false;CheckoutClients.PaymentResponse payment=null;try{for(var item:cart.items())clients.reserve(new CheckoutClients.ReservationRequest(order.id(),item.productId(),item.quantity()));reserved=true;payment=clients.authorize(new CheckoutClients.PaymentRequest(order.id(),request.idempotencyKey()+":payment",cart.subtotal(),cart.currency(),request.cardLast4()));if(payment==null||!"AUTHORIZED".equals(payment.status())){clients.releaseReservations(order.id());clients.failOrder(order.id());return new CheckoutResponse(order.id(),payment==null?null:payment.id(),"PAYMENT_FAILED",cart.subtotal(),cart.currency());}clients.commitReservations(order.id());committed=true;clients.confirmOrder(order.id(),payment.id());try{clients.clearCart(request.userId());}catch(Exception clearFailure){log.warn("CART_CLEAR_FAILED_AFTER_CONFIRMED orderId={} userId={}",order.id(),request.userId(),clearFailure);}return new CheckoutResponse(order.id(),payment.id(),"CONFIRMED",cart.subtotal(),cart.currency());}catch(RuntimeException failure){try{if(committed)clients.compensateReservations(order.id());else if(reserved)clients.releaseReservations(order.id());}catch(Exception compensation){failure.addSuppressed(compensation);}if(payment!=null&&"AUTHORIZED".equals(payment.status()))try{clients.refund(payment.id(),"Checkout compensation for order "+order.id());}catch(Exception refund){failure.addSuppressed(refund);}try{clients.failOrder(order.id());}catch(Exception orderFailure){failure.addSuppressed(orderFailure);}throw failure;}}
}
